import{_ as a,o as e,c as o,a3 as d}from"./chunks/framework.0hMh3lCe.js";const u=JSON.parse('{"title":"IEC61850 报告上送与 DataModel 并发读取崩溃修复","description":"","frontmatter":{},"headers":[],"relativePath":"changelog/iec61850/23-iec61850-report-datamodel-concurrency-crash-fix.md","filePath":"changelog/iec61850/23-iec61850-report-datamodel-concurrency-crash-fix.md","lastUpdated":1783127200000}'),l={name:"changelog/iec61850/23-iec61850-report-datamodel-concurrency-crash-fix.md"};function i(r,t,c,h,n,s){return e(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="iec61850-报告上送与-datamodel-并发读取崩溃修复" tabindex="-1">IEC61850 报告上送与 DataModel 并发读取崩溃修复 <a class="header-anchor" href="#iec61850-报告上送与-datamodel-并发读取崩溃修复" aria-label="Permalink to &quot;IEC61850 报告上送与 DataModel 并发读取崩溃修复&quot;">​</a></h1><blockquote><p>版本：1.0<br> 日期：2026-07-04<br> 分类：Reports / DataModel / MMS 连接 / 并发安全 / ICD 导出回归 / Bug 修复<br> 状态：已实施</p></blockquote><h2 id="_1-问题现象" tabindex="-1">1. 问题现象 <a class="header-anchor" href="#_1-问题现象" aria-label="Permalink to &quot;1. 问题现象&quot;">​</a></h2><p>IEC61850 客户端使能 BRCB 或 URCB 后，设备会在 libIEC61850 的接收线程中主动上送报告。此时如果用户同时进入 DataModel 页面、重新发现模型或读取 DataSet，旧实现可能让报告回调和同步 MMS 请求竞争同一个原生 <code>IedConnection</code>，严重时整个 Python 进程直接退出，无法由常规异常处理捕获。</p><p>该问题具有明显的并发特征：单独读取 DataModel 或单独订阅报告通常正常，只有报告持续上送期间执行模型读取才容易触发。</p><h2 id="_2-根因分类" tabindex="-1">2. 根因分类 <a class="header-anchor" href="#_2-根因分类" aria-label="Permalink to &quot;2. 根因分类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分类</th><th>根因</th><th>风险</th></tr></thead><tbody><tr><td>连接复用</td><td>报告接收、RCB 配置、模型发现和测点读取共用同一个 MMS association</td><td>同步请求与异步回调互相阻塞或重入</td></tr><tr><td>GIL 协作</td><td>部分阻塞式 SWIG 原生调用未优先使用释放 GIL 的包装入口</td><td>原生接收线程等待进入 Python 回调时可能形成僵持</td></tr><tr><td>生命周期</td><td>断线或重连时可能在报告回调尚未退出前销毁原生连接</td><td>回调继续访问失效句柄，导致进程级崩溃</td></tr><tr><td>回调作用域</td><td>回调注册表按进程管理，清理时缺少 connection 归属过滤</td><td>一条连接重连可能误清理其他连接或客户端的报告</td></tr><tr><td>长操作保护</td><td>完整模型发现未覆盖整个原生连接生命周期锁</td><td>发现过程中可能被断线或重连销毁底层句柄</td></tr></tbody></table><h2 id="_3-修复方案" tabindex="-1">3. 修复方案 <a class="header-anchor" href="#_3-修复方案" aria-label="Permalink to &quot;3. 修复方案&quot;">​</a></h2><h3 id="_3-1-双-mms-连接隔离" tabindex="-1">3.1 双 MMS 连接隔离 <a class="header-anchor" href="#_3-1-双-mms-连接隔离" aria-label="Permalink to &quot;3.1 双 MMS 连接隔离&quot;">​</a></h3><p>客户端现在为同一台 IED 建立两个彼此独立的 association：</p><table tabindex="0"><thead><tr><th>连接</th><th>职责</th></tr></thead><tbody><tr><td>主连接</td><td>模型发现、DataModel、DataSet、单点读写和元数据读取</td></tr><tr><td>报告连接</td><td>RCB 参数读写、报告使能、GI 和主动报告接收</td></tr></tbody></table><p>报告连接建立失败不会破坏已成功建立的主连接，Reports 插件在实际使用前会按需重连。主连接完成模型发现后，会把逻辑设备列表和模型前缀同步给报告连接，保证 RCB 引用解析一致。</p><p>这种拆分从 association 层消除了“同步模型读取占用连接时，报告接收线程又要在同一连接上进入 Python”的冲突。</p><h3 id="_3-2-原生阻塞调用统一释放-gil" tabindex="-1">3.2 原生阻塞调用统一释放 GIL <a class="header-anchor" href="#_3-2-原生阻塞调用统一释放-gil" aria-label="Permalink to &quot;3.2 原生阻塞调用统一释放 GIL&quot;">​</a></h3><p>新增 <code>call_gil_safe()</code> 入口。对于 <code>pyiec61850-ng</code> 已提供的 <code>pyWrap_*</code> 方法，优先调用会释放 GIL 的包装函数；旧版绑定不存在包装函数时，再兼容回退到原始方法。</p><p>当前已覆盖以下高风险路径：</p><ul><li>DataModel、DataSet 和普通测点的 <code>readObject</code>；</li><li>元数据读取；</li><li>RCB 的 <code>getRCBValues</code>、<code>setRCBValues</code>；</li><li>模型发现期间的运行时值读取。</li></ul><h3 id="_3-3-安全断开顺序" tabindex="-1">3.3 安全断开顺序 <a class="header-anchor" href="#_3-3-安全断开顺序" aria-label="Permalink to &quot;3.3 安全断开顺序&quot;">​</a></h3><p>断开客户端时严格执行以下顺序：</p><ol><li>对当前报告连接上的活跃 RCB 写入 <code>RptEna=false</code>；</li><li>给已到达接收线程的最后一批报告留出处理窗口；</li><li>等待已经进入 Python 的报告回调退出；</li><li>注销当前 association 的回调和订阅者；</li><li>先断开报告连接，再断开主连接。</li></ol><p>回调处理器会按 connection 记录正在执行的回调数量，并通过条件变量等待排空。即使等待超时，也会输出明确日志，避免无声挂起。</p><h3 id="_3-4-回调按连接隔离" tabindex="-1">3.4 回调按连接隔离 <a class="header-anchor" href="#_3-4-回调按连接隔离" aria-label="Permalink to &quot;3.4 回调按连接隔离&quot;">​</a></h3><p>每条回调注册信息新增所属 connection。查询活跃报告、复用相同 <code>RptId</code> 的订阅者以及批量清理回调时，都只作用于指定 association。</p><p>普通数据连接重连不再全局执行 <code>shutdown_all()</code>，从而避免误删独立报告连接或另一个客户端实例的订阅。</p><h3 id="_3-5-模型发现生命周期保护" tabindex="-1">3.5 模型发现生命周期保护 <a class="header-anchor" href="#_3-5-模型发现生命周期保护" aria-label="Permalink to &quot;3.5 模型发现生命周期保护&quot;">​</a></h3><p>完整在线模型发现和远程刷新现在都在 <code>native_operation()</code> 保护区内执行。只要发现尚未结束，断线或重连就不能销毁同一个原生连接句柄。DataModel 插件的 LN、DO、DA/BDA 浏览和描述读取也复用同一保护机制。</p><h2 id="_4-icd-xml-导出回归分类" tabindex="-1">4. ICD/XML 导出回归分类 <a class="header-anchor" href="#_4-icd-xml-导出回归分类" aria-label="Permalink to &quot;4. ICD/XML 导出回归分类&quot;">​</a></h2><p>本次并发修复扩大回归范围后，完整测试曾出现 23 项 ICD/XML 导出失败，但同一组测试单独运行时全部通过。排查确认，失败并非 23 个独立的导出算法缺陷，而是两个测试文件仍从 <code>proto.*</code> 导入模块；在安装过旧版项目包的虚拟环境中，这会加载 <code>site-packages/proto</code> 的旧代码，而业务和其他测试使用的是工作区内的 <code>src.proto.*</code>。</p><p>相关测试已统一改为 <code>src.proto.*</code> 规范导入，并删除了错误拼接到 <code>src/src</code> 的 <code>sys.path</code> 修改。这样无论单独运行还是整目录运行，测试都只验证当前工作区代码，不再受旧安装包和执行顺序影响。</p><p>导出断言按以下类别继续保留：</p><ul><li>IED 名称推断与 LD 实例名拆分；</li><li>FCDA 的 FC、前缀和空属性规范化；</li><li>DOType、DAType、EnumType 生成与去重；</li><li>q、t、origin、setMag 等 CDC/结构类型映射；</li><li>BRCB/URCB 实例聚合和 <code>RptEnabled max</code>；</li><li>标准 SCL 与自定义 <code>ServerModel</code> XML 两种导出格式。</li></ul><p>ICD/XML 导出器专项共 75 项测试。该组问题与双连接实现没有运行时耦合，但被纳入同一次 IEC61850 回归，防止连接修复掩盖模型导出兼容性问题。</p><h2 id="_5-兼容性说明" tabindex="-1">5. 兼容性说明 <a class="header-anchor" href="#_5-兼容性说明" aria-label="Permalink to &quot;5. 兼容性说明&quot;">​</a></h2><ul><li><code>IEC61850Client</code> 的公开连接、读取、写入和报告 API 保持不变；</li><li><code>is_connected</code> 仍表示主连接状态；</li><li>报告连接可独立恢复，不影响主连接上的模型浏览和测点操作；</li><li>不支持 <code>pyWrap_*</code> 的旧版绑定仍可通过原生函数兼容运行；</li><li>报告回调缓存、GI 路由和前端报告数据格式保持不变。</li></ul><h2 id="_6-验证重点" tabindex="-1">6. 验证重点 <a class="header-anchor" href="#_6-验证重点" aria-label="Permalink to &quot;6. 验证重点&quot;">​</a></h2><p>新增回归测试覆盖：</p><ul><li>主连接与报告连接不是同一对象；</li><li>连接顺序为主连接后报告连接；</li><li>断开顺序为报告排空、报告断开、主连接断开；</li><li>GIL-safe 包装函数优先于原始原生调用；</li><li>一条连接的 <code>shutdown_all()</code> 不影响其他连接；</li><li>RCB 禁用发生在回调等待和订阅注销之前。</li></ul><h3 id="_6-1-自动化回归" tabindex="-1">6.1 自动化回归 <a class="header-anchor" href="#_6-1-自动化回归" aria-label="Permalink to &quot;6.1 自动化回归&quot;">​</a></h3><table tabindex="0"><thead><tr><th>验证项</th><th>结果</th></tr></thead><tbody><tr><td>IEC61850 非设备依赖测试</td><td>169 项通过</td></tr><tr><td>ICD/XML 多格式导出专项</td><td>75 项通过，整套执行不再加载旧安装包</td></tr><tr><td>Ruff 与 Python 编译检查</td><td>通过</td></tr><tr><td>VitePress 文档构建</td><td>通过</td></tr></tbody></table><h3 id="_6-2-真实-mms-冒烟" tabindex="-1">6.2 真实 MMS 冒烟 <a class="header-anchor" href="#_6-2-真实-mms-冒烟" aria-label="Permalink to &quot;6.2 真实 MMS 冒烟&quot;">​</a></h3><p>在本机 <code>127.0.0.1:102</code> 的真实 MMS 服务上完成双连接冒烟：</p><ul><li>主连接与报告连接均建立成功，两个底层连接对象彼此独立；</li><li>模型发现完成：25 个 LD、59 个 LN、4566 个 DO、18252 个 DA、34 个 DataSet、272 个 RCB；</li><li>模型发现后报告连接仍保持可用；</li><li>客户端断开后，主连接和报告连接状态均为未连接；</li><li>整个建立、发现和安全断开过程无崩溃、无回调残留。</li></ul><p>后续现场长稳验证应继续覆盖“RCB 持续主动上送期间反复读取 DataModel/DataSet”的压力场景，以验证不同厂商 IED 和网络延迟下的长期表现。</p><h2 id="_7-结果" tabindex="-1">7. 结果 <a class="header-anchor" href="#_7-结果" aria-label="Permalink to &quot;7. 结果&quot;">​</a></h2><p>修复后，报告主动上送与 DataModel/DataSet 同步读取分别运行在独立 MMS association 上；阻塞式原生调用能够让出 GIL；断线前会先停止报告并排空 Python 回调。原有最危险的同连接重入和失效句柄访问路径已被切断。</p>',45)])])}const _=a(l,[["render",i]]);export{u as __pageData,_ as default};
